import { useCallback, useEffect, useRef, useState } from "react";
// eslint-disable-next-line import/no-unresolved -- virtual module generated by the plugin at build time, typed in autoi18n-virtual.d.ts
import { t } from "virtual:autoi18n";

type Status = "shared" | "private" | "archived";
type Filter = "all" | Status;
type SortKey = "name" | "pages" | "updated";
type SortDir = "asc" | "desc";

interface DocumentItem {
  id: number;
  name: string;
  pages: number;
  sizeMb: number;
  status: Status;
  owner: string;
  updated: string;
}

interface Override {
  name?: string;
  status?: Status;
}

const FILTERS: Filter[] = ["all", "shared", "private", "archived"];
const QUOTA_MB = 500;
const ARIA_SORT: Record<SortDir, "ascending" | "descending"> = { asc: "ascending", desc: "descending" };

const comparators: Record<SortKey, (a: DocumentItem, b: DocumentItem) => number> = {
  name: (a, b) => a.name.localeCompare(b.name),
  pages: (a, b) => a.pages - b.pages,
  updated: (a, b) => a.updated.localeCompare(b.updated),
};

